package com.hbm.client.reactor.rbmk.fuel;
import com.hbm.machine.reactor.rbmk.fuel.*;import java.util.*;import me.shedaniel.math.*;import me.shedaniel.rei.api.client.gui.Renderer;import me.shedaniel.rei.api.client.gui.widgets.*;import me.shedaniel.rei.api.client.plugins.REIClientPlugin;import me.shedaniel.rei.api.client.registry.category.CategoryRegistry;import me.shedaniel.rei.api.client.registry.display.*;import me.shedaniel.rei.api.client.registry.entry.EntryRegistry;import me.shedaniel.rei.api.common.category.CategoryIdentifier;import me.shedaniel.rei.api.common.display.basic.BasicDisplay;import me.shedaniel.rei.api.common.entry.*;import me.shedaniel.rei.api.common.util.EntryStacks;import me.shedaniel.rei.forge.REIPluginClient;import net.minecraft.network.chat.Component;
@REIPluginClient public final class RbmkFuelReiPlugin implements REIClientPlugin {
 private static final CategoryIdentifier<Display> DISASSEMBLY=CategoryIdentifier.of("hbm","rbmk_disassembly"),COOLING=CategoryIdentifier.of("hbm","rbmk_fuel_cooling");@Override public void registerCategories(CategoryRegistry event){event.add(new Category(false),new Category(true));event.addWorkstations(DISASSEMBLY,EntryStacks.of(RbmkFuelViews.catalyst(false)));event.addWorkstations(COOLING,EntryStacks.of(RbmkFuelViews.catalyst(true)));}@Override public void registerDisplays(DisplayRegistry event){for(var view:RbmkFuelViews.disassembly())event.add(new Display(view));for(var view:RbmkFuelViews.cooling())event.add(new Display(view));}@Override public void registerEntries(EntryRegistry event){for(var stack:RbmkFuelContent.allStacks())event.addEntry(EntryStacks.of(stack));}@Override public void registerItemComparators(me.shedaniel.rei.api.common.entry.comparison.ItemComparatorRegistry event){for(var holder:RbmkFuelContent.PELLETS){var item=holder.get();event.register((context,stack)->item.metadata(stack),item);}for(var holder:RbmkFuelContent.RODS)event.register((context,stack)->RbmkFuelViews.hot(stack)?1:0,holder.get());}
 private static final class Display extends BasicDisplay{final RbmkFuelViews.View view;Display(RbmkFuelViews.View view){super(List.of(EntryIngredient.of(EntryStacks.of(view.input()))),List.of(EntryIngredient.of(EntryStacks.of(view.output()))));this.view=view;}@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return view.cooling()?COOLING:DISASSEMBLY;}}
 private static final class Category implements DisplayCategory<Display>{final boolean cooling;Category(boolean cooling){this.cooling=cooling;}@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return cooling?COOLING:DISASSEMBLY;}@Override public Component getTitle(){return Component.translatable(cooling?"rbmk.cooling":"rbmk.disassembly");}@Override public Renderer getIcon(){return EntryStacks.of(RbmkFuelViews.catalyst(cooling));}@Override public int getDisplayWidth(Display display){return 166;}@Override public int getDisplayHeight(){return 65;}@Override public List<Widget> setupDisplay(Display display,Rectangle bounds){return List.of(Widgets.createDrawableWidget((graphics,x,y,partial)->RbmkFuelViews.draw(graphics,bounds.x,bounds.y)),Widgets.createSlot(new Point(bounds.x+48,bounds.y+24)).entries(display.getInputEntries().getFirst()).disableBackground().markInput(),Widgets.createSlot(new Point(bounds.x+102,bounds.y+24)).entries(display.getOutputEntries().getFirst()).disableBackground().markOutput(),Widgets.createSlot(new Point(bounds.x+75,bounds.y+31)).entry(EntryStacks.of(RbmkFuelViews.catalyst(cooling))).disableBackground());}}
}
